import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Студия интерьеров: сайт из нескольких страниц с портфолио, блогом и заявками"}>
      <p>{"Мы студия дизайна интерьеров «Линия» в Екатеринбурге, работаем шестой год, в команде четыре дизайнера и комплектатор. Сейчас у нас одностраничник на конструкторе, и он не продаёт. Нужен нормальный сайт из нескольких страниц: главная с лучшими работами, страницы услуг (дизайн-проект квартиры, дизайн дома, авторский надзор, комплектация мебелью), портфолио — каждый проект отдельной страницей с фото, площадью и стилем, страница о студии с командой, блог со статьями про ремонт и планировки, контакты. На каждой странице кнопка «Обсудить проект»: человек оставляет имя, телефон, площадь объекта и примерный бюджет, заявка приходит нам на почту и в список заявок. Статьи и проекты добавляет наш администратор сам, без программиста. Стиль — спокойный, много воздуха, хорошие фото, никакой кричащей рекламы. С иностранными клиентами общается наш партнёр клиент, его рабочий номер клиент — его можно указать на странице контактов."}</p>
      <ul>
        <li>{"Форма заявки"}</li>
        <li>{"Портфолио проектов"}</li>
        <li>{"Блог со статьями"}</li>
        <li>{"Страницы услуг"}</li>
      </ul>
      <p>{"Заявка приходит на почту"}</p>
      <p>{"Администратор сам публикует статьи и проекты"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
